{"command":"cd /workspace && cat > main.go <<'EOF'
// Command dupl finds code clones in Go source files.
package main

import (
	"bufio"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"dupl/internal/clones"
	"dupl/internal/gosyntax"
	"dupl/internal/output"
	"dupl/internal/stree"
	"dupl/internal/tree"
)

const usageText = `Usage: dupl [flags] [paths]

Paths:
  If the given path is a file, dupl will use it regardless of
  the file extension. If it is a directory, it will recursively
  search for *.go files in that directory.

  If no path is given, dupl will recursively search for *.go
  files in the current directory.

Flags:
  -files
    	read file names from stdin one at each line
  -html
    	output the results as HTML, including duplicate code fragments
  -plumbing
    	plumbing (easy-to-parse) output for consumption by scripts or tools
  -t, -threshold size
    	minimum token sequence size as a clone (default 15)
  -vendor
    	check files in vendor directory
  -v, -verbose
    	explain what is being done

Examples:
  dupl -t 100
    	Search clones in the current directory of size at least
    	100 tokens.
  dupl $(find app/ -name '*_test.go')
    	Search for clones in tests in the app directory.
  find app/ -name '*_test.go' |dupl -files
    	The same as above.`

var (
	optVendor    bool
	optVerbose   bool
	optThreshold int
	optFiles     bool
	optHTML      bool
	optPlumbing  bool
)

func printUsage() {
	fmt.Fprintln(os.Stderr, usageText)
	os.Exit(2)
}

func main() {
	flag.BoolVar(&optFiles, "files", false, "")
	flag.BoolVar(&optHTML, "html", false, "")
	flag.BoolVar(&optPlumbing, "plumbing", false, "")
	flag.IntVar(&optThreshold, "threshold", 15, "")
	flag.IntVar(&optThreshold, "t", 15, "")
	flag.BoolVar(&optVendor, "vendor", false, "")
	flag.BoolVar(&optVerbose, "verbose", false, "")
	flag.BoolVar(&optVerbose, "v", false, "")
	flag.Usage = printUsage
	flag.Parse()

	if optHTML && optPlumbing {
		log.Fatal("you can have either plumbing or HTML output")
	}

	roots := []string{"."}
	if flag.NArg() > 0 {
		roots = flag.Args()
	}

	if optVerbose {
		log.Println("Building suffix tree")
	}

	var names <-chan string
	if optFiles {
		names = namesFromStdin()
	} else {
		names = walkRoots(roots)
	}

	// Parse every file and build one long token stream.
	st := stree.New()
	var stream []*tree.Node
	for name := range names {
		root, err := gosyntax.ParseFile(name)
		if err != nil {
			log.Println(err)
			continue
		}
		seq := tree.Flatten(root)
		stream = append(stream, seq...)
		for _, n := range seq {
			st.Add(n.Kind)
		}
	}
	// Terminate the stream with a unique token.
	st.Add(-1)

	if optVerbose {
		log.Println("Searching for clones")
	}

	groups := make(map[string][][]*tree.Node)
	st.Repeats(optThreshold, func(positions []int, length int) {
		m := clones.Extract(stream, positions, length, optThreshold)
		if len(m.Frags) > 0 {
			groups[m.Hash] = append(groups[m.Hash], m.Frags...)
		}
	})

	var pr output.Printer
	switch {
	case optHTML:
		pr = output.NewHTML(os.Stdout, os.ReadFile)
	case optPlumbing:
		pr = output.NewPlumbing(os.Stdout, os.ReadFile)
	default:
		pr = output.NewText(os.Stdout, os.ReadFile)
	}
	if err := emit(pr, groups); err != nil {
		log.Fatal(err)
	}
}

func emit(pr output.Printer, groups map[string][][]*tree.Node) error {
	hashes := make([]string, 0, len(groups))
	for h := range groups {
		hashes = append(hashes, h)
	}
	sort.Strings(hashes)

	if err := pr.Header(); err != nil {
		return err
	}
	for _, h := range hashes {
		frags := dedup(groups[h])
		if len(frags) < 2 {
			continue
		}
		if err := pr.Group(frags); err != nil {
			return err
		}
	}
	return pr.Footer()
}

// dedup drops fragments starting at an already seen place.
func dedup(frags [][]*tree.Node) [][]*tree.Node {
	type key struct {
		file string
		off  int
	}
	seen := make(map[key]bool)
	var out [][]*tree.Node
	for _, f := range frags {
		k := key{f[0].File, f[0].Start}
		if seen[k] {
			continue
		}
		seen[k] = true
		out = append(out, f)
	}
	return out
}

func namesFromStdin() <-chan string {
	ch := make(chan string)
	go func() {
		sc := bufio.NewScanner(os.Stdin)
		for sc.Scan() {
			ch <- strings.TrimPrefix(sc.Text(), "./")
		}
		close(ch)
	}()
	return ch
}

const sep = string(filepath.Separator)

func isVendored(p string) bool {
	return strings.HasPrefix(p, "vendor"+sep) || strings.Contains(p, sep+"vendor"+sep)
}

func walkRoots(roots []string) <-chan string {
	ch := make(chan string)
	go func() {
		for _, r := range roots {
			fi, err := os.Lstat(r)
			if err != nil {
				log.Fatal(err)
			}
			if !fi.IsDir() {
				ch <- r
				continue
			}
			filepath.Walk(r, func(p string, info os.FileInfo, err error) error {
				if !optVendor && isVendored(p) {
					return nil
				}
				if !info.IsDir() && strings.HasSuffix(info.Name(), ".go") {
					ch <- p
				}
				return nil
			})
		}
		close(ch)
	}()
	return ch
}
EOF"}

