// Package tree holds the language independent syntax tree used for
// clone detection.
package tree

// Node is a single element of a syntax tree.
type Node struct {
	Kind     int
	File     string
	Start    int // byte offset of the first character
	Stop     int // byte offset just past the last character
	Kids     []*Node
	Size     int // number of descendants
}

// Add appends children to n.
func (n *Node) Add(kids ...*Node) {
	n.Kids = append(n.Kids, kids...)
}

// Flatten lists the nodes of the tree rooted at n in pre-order and fills in
// the Size of every node.
func Flatten(n *Node) []*Node {
	out := make([]*Node, 0, 16)
	var visit func(*Node) int
	visit = func(x *Node) int {
		out = append(out, x)
		total := 0
		for _, k := range x.Kids {
			total += visit(k)
		}
		x.Size = total
		return total + 1
	}
	visit(n)
	return out
}
EOF"}

