// Package gosyntax converts Go source files into generic syntax trees.
package gosyntax

import (
	"go/ast"
	"go/parser"
	"go/token"

	"dupl/internal/tree"
)

// Node kinds.
const (
	kBad = iota
	kFile
	kArrayType
	kAssignStmt
	kBasicLit
	kBinaryExpr
	kBlockStmt
	kBranchStmt
	kCallExpr
	kCaseClause
	kChanType
	kCommClause
	kCompositeLit
	kDeclStmt
	kDeferStmt
	kEllipsis
	kEmptyStmt
	kExprStmt
	kField
	kFieldList
	kForStmt
	kFuncDecl
	kFuncLit
	kFuncType
	kGenDecl
	kGoStmt
	kIdent
	kIfStmt
	kIncDecStmt
	kIndexExpr
	kInterfaceType
	kKeyValueExpr
	kLabeledStmt
	kMapType
	kParenExpr
	kRangeStmt
	kReturnStmt
	kSelectStmt
	kSelectorExpr
	kSendStmt
	kSliceExpr
	kStarExpr
	kStructType
	kSwitchStmt
	kTypeAssertExpr
	kTypeSpec
	kTypeSwitchStmt
	kUnaryExpr
	kValueSpec
)

// ParseFile parses the named Go file and converts it.
func ParseFile(name string) (*tree.Node, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, name, nil, 0)
	if err != nil {
		return nil, err
	}
	c := &converter{fset: fset, name: name}
	return c.conv(f), nil
}

type converter struct {
	fset *token.FileSet
	name string
}

func (c *converter) offset(p token.Pos) int {
	return c.fset.File(p).Offset(p)
}

func (c *converter) conv(an ast.Node) *tree.Node {
	n := &tree.Node{File: c.name}
	n.Start = c.offset(an.Pos())
	n.Stop = c.offset(an.End())

	switch x := an.(type) {
	case *ast.ArrayType:
		n.Kind = kArrayType
		if x.Len != nil {
			n.Add(c.conv(x.Len))
		}
		n.Add(c.conv(x.Elt))

	case *ast.AssignStmt:
		n.Kind = kAssignStmt
		for i := len(x.Rhs) - 1; i >= 0; i-- {
			n.Add(c.conv(x.Rhs[i]))
		}
		for _, e := range x.Lhs {
			n.Add(c.conv(e))
		}

	case *ast.BasicLit:
		n.Kind = kBasicLit

	case *ast.BinaryExpr:
		n.Kind = kBinaryExpr
		n.Add(c.conv(x.X), c.conv(x.Y))

	case *ast.BlockStmt:
		n.Kind = kBlockStmt
		for _, s := range x.List {
			n.Add(c.conv(s))
		}

	case *ast.BranchStmt:
		n.Kind = kBranchStmt
		if x.Label != nil {
			n.Add(c.conv(x.Label))
		}

	case *ast.CallExpr:
		n.Kind = kCallExpr
		n.Add(c.conv(x.Fun))
		for _, a := range x.Args {
			n.Add(c.conv(a))
		}

	case *ast.CaseClause:
		n.Kind = kCaseClause
		for _, e := range x.List {
			n.Add(c.conv(e))
		}
		for _, s := range x.Body {
			n.Add(c.conv(s))
		}

	case *ast.ChanType:
		n.Kind = kChanType
		n.Add(c.conv(x.Value))

	case *ast.CommClause:
		n.Kind = kCommClause
		if x.Comm != nil {
			n.Add(c.conv(x.Comm))
		}
		for _, s := range x.Body {
			n.Add(c.conv(s))
		}

	case *ast.CompositeLit:
		n.Kind = kCompositeLit
		if x.Type != nil {
			n.Add(c.conv(x.Type))
		}
		for _, e := range x.Elts {
			n.Add(c.conv(e))
		}

	case *ast.DeclStmt:
		n.Kind = kDeclStmt
		n.Add(c.conv(x.Decl))

	case *ast.DeferStmt:
		n.Kind = kDeferStmt
		n.Add(c.conv(x.Call))

	case *ast.Ellipsis:
		n.Kind = kEllipsis
		if x.Elt != nil {
			n.Add(c.conv(x.Elt))
		}

	case *ast.EmptyStmt:
		n.Kind = kEmptyStmt

	case *ast.ExprStmt:
		n.Kind = kExprStmt
		n.Add(c.conv(x.X))

	case *ast.Field:
		n.Kind = kField
		for _, id := range x.Names {
			n.Add(c.conv(id))
		}
		n.Add(c.conv(x.Type))

	case *ast.FieldList:
		n.Kind = kFieldList
		for _, f := range x.List {
			n.Add(c.conv(f))
		}

	case *ast.File:
		n.Kind = kFile
		for _, d := range x.Decls {
			if g, ok := d.(*ast.GenDecl); ok && g.Tok == token.IMPORT {
				continue
			}
			n.Add(c.conv(d))
		}

	case *ast.ForStmt:
		n.Kind = kForStmt
		if x.Init != nil {
			n.Add(c.conv(x.Init))
		}
		if x.Cond != nil {
			n.Add(c.conv(x.Cond))
		}
