// Package stree implements an online (Ukkonen) suffix tree over integer
// tokens and a search for maximal repeats in it.
package stree

import (
	"math"
	"sort"
)

const open = math.MaxInt32

type edge struct {
	from, to int // inclusive token range; to == open for leaves
	dst      *node
}

type node struct {
	edges  []*edge
	suffix *node
}

// Tree is a suffix tree built incrementally token by token.
type Tree struct {
	toks   []int
	root   *node
	bottom *node // auxiliary state above the root
	act    *node
	k      int
}

// New returns an empty tree.
func New() *Tree {
	t := &Tree{root: &node{}, bottom: &node{}}
	t.root.suffix = t.bottom
	t.act = t.root
	return t
}

func (t *Tree) edgeFor(s *node, tok int) *edge {
	for _, e := range s.edges {
		if t.toks[e.from] == tok {
			return e
		}
	}
	return nil
}

// Add appends a token to the indexed sequence.
func (t *Tree) Add(tok int) {
	t.toks = append(t.toks, tok)
	i := len(t.toks) - 1
	prev := t.root
	done, r := t.testSplit(t.act, t.k, i-1, tok)
	for !done {
		r.edges = append(r.edges, &edge{from: i, to: open, dst: &node{}})
		if prev != t.root {
			prev.suffix = r
		}
		prev = r
		t.act, t.k = t.canon(t.act.suffix, t.k, i-1)
		done, r = t.testSplit(t.act, t.k, i-1, tok)
	}
	if prev != t.root {
		prev.suffix = t.act
	}
	t.act, t.k = t.canon(t.act, t.k, i)
}

func (t *Tree) testSplit(s *node, k, p, tok int) (bool, *node) {
	if k <= p {
		if s == t.bottom {
			return true, s
		}
		e := t.edgeFor(s, t.toks[k])
		at := e.from + p - k + 1
		if t.toks[at] == tok {
			return true, s
		}
		r := &node{}
		r.edges = append(r.edges, &edge{from: at, to: e.to, dst: e.dst})
		e.to = at - 1
		e.dst = r
		return false, r
	}
	if s == t.bottom {
		return true, s
	}
	return t.edgeFor(s, tok) != nil, s
}

func (t *Tree) canon(s *node, k, p int) (*node, int) {
	for k <= p {
		if s == t.bottom {
			s = t.root
			k++
			continue
		}
		e := t.edgeFor(s, t.toks[k])
		if e.to-e.from > p-k {
			break
		}
		k += e.to - e.from + 1
		s = e.dst
	}
	return s, k
}

// Repeats reports every left-maximal repeat of at least min tokens. For
// each repeat the start positions and length are passed to fn.
func (t *Tree) Repeats(min int, fn func(pos []int, length int)) {
	t.walk(t.root, 0, 0, min, fn)
}

// ctx groups suffix start positions by the token preceding them.
type ctx map[int]*[]int

func (t *Tree) walk(s *node, from, depth, min int, fn func([]int, int)) ctx {
	out := make(ctx)
	if len(s.edges) == 0 {
		start := from - depth
		prevTok := 0
		if start > 0 {
			prevTok = t.toks[start-1]
		}
		lst := []int{start}
		out[prevTok] = &lst
		return out
	}
	for _, e := range s.edges {
		var d int
		if e.to == open {
			d = open // leaves are always long enough
		} else {
			d = depth + e.to - e.from + 1
		}
		sub := t.walk(e.dst, e.from, depth+e.to-e.from+1, min, fn)
		if e.to == open || d >= min {
			for key, lst := range sub {
				if have, ok := out[key]; ok {
					*have = append(*have, (*lst)...)
				} else {
					out[key] = lst
				}
			}
		}
	}
	if depth >= min && len(out) > 1 {
		keys := make([]int, 0, len(out))
		for key := range out {
			keys = append(keys, key)
		}
		sort.Ints(keys)
		var pos []int
		for _, key := range keys {
			pos = append(pos, (*out[key])...)
		}
		fn(pos, depth)
	}
	return out
}
EOF"}

