{"command":"cd /workspace/internal && cat > clones/clones.go <<'EOF'
// Package clones turns raw token repeats into groups of complete syntax
// units.
package clones

import (
	"crypto/sha1"

	"dupl/internal/tree"
)

// Match is a set of equivalent fragments sharing the same hash.
type Match struct {
	Hash  string
	Frags [][]*tree.Node
}

// Extract finds the complete syntax units of a repeat found at the given
// positions of the stream.
func Extract(stream []*tree.Node, pos []int, length, min int) Match {
	if len(pos) == 0 {
		return Match{}
	}
	first := stream[pos[0] : pos[0]+length]
	idx := unitStarts(first, min)

	if cnt := len(idx); cnt > 0 {
		last := idx[cnt-1]
		ref := first[last]
		for _, p := range pos[1:] {
			if stream[p+last].Size != ref.Size {
				idx = idx[:cnt-1]
				break
			}
		}
	}
	if len(idx) == 0 || repetitive(idx, first) || crossesFiles(idx, first) {
		return Match{}
	}

	m := Match{Frags: make([][]*tree.Node, len(pos))}
	for i, p := range pos {
		frag := make([]*tree.Node, len(idx))
		for j, off := range idx {
			frag[j] = stream[p+off]
		}
		m.Frags[i] = frag
	}
	last := idx[len(idx)-1]
	m.Hash = hashKinds(first[idx[0] : last+first[last].Size])
	return m
}

// unitStarts returns the offsets of the last run of consecutive complete
// syntax units which are big enough.
func unitStarts(seq []*tree.Node, min int) []int {
	var idx []int
	broken := false
	for i := 0; i < len(seq); {
		n := seq[i]
		if n.Size >= len(seq)-i {
			// the unit is not complete; descend into it
			i++
			broken = true
			continue
		}
		if n.Size+1 < min {
			broken = true
		} else {
			if broken {
				idx = idx[:0]
				broken = false
			}
			idx = append(idx, i)
		}
		i += n.Size + 1
	}
	return idx
}

// repetitive reports whether the units form a periodic pattern.
func repetitive(idx []int, seq []*tree.Node) bool {
	cnt := len(idx)
	if cnt <= 1 {
		return false
	}
	periods := make(map[int]bool)
	for p := 1; p <= cnt/2; p++ {
		if cnt%p == 0 {
			periods[p] = true
		}
	}
	for i := 0; i < idx[cnt/2]; i++ {
		a := seq[i+idx[0]]
	next:
		for p := range periods {
			for j := p; j < cnt; j += p {
				k := i + idx[j]
				if k < len(seq) {
					b := seq[k]
					if a.Size == b.Size && a.Kind == b.Kind {
						continue
					}
				} else if i >= idx[p] {
					return true
				}
				delete(periods, p)
				continue next
			}
		}
		if len(periods) == 0 {
			return false
		}
	}
	return true
}

func crossesFiles(idx []int, seq []*tree.Node) bool {
	if len(idx) < 2 {
		return false
	}
	f := seq[idx[0]].File
	for _, i := range idx[1:] {
		if seq[i].File != f {
			return true
		}
	}
	return false
}

func hashKinds(seq []*tree.Node) string {
	b := make([]byte, len(seq))
	for i, n := range seq {
		b[i] = byte(n.Kind)
	}
	sum := sha1.Sum(b)
	return string(sum[:])
}
EOF"}

