		if cnt%p == 0 {
			periods[p] = true
		}
	}
	for i := 0; i < idx[cnt/2]; i++ {
		a := seq[i+idx[0]]
	next:
		for p := range periods {
			for j := p; j < cnt; j += p {
				k := i + idx[j]
				if k < len(seq) {
					b := seq[k]
					if a.Size == b.Size && a.Kind == b.Kind {
						continue
					}
				} else if i >= idx[p] {
					return true
				}
				delete(periods, p)
				continue next
			}
		}
		if len(periods) == 0 {
			return false
		}
	}
	return true
}

func crossesFiles(idx []int, seq []*tree.Node) bool {
	if len(idx) < 2 {
		return false
	}
	f := seq[idx[0]].File
	for _, i := range idx[1:] {
		if seq[i].File != f {
			return true
		}
	}
	return false
}

func hashKinds(seq []*tree.Node) string {
	b := make([]byte, len(seq))
	for i, n := range seq {
		b[i] = byte(n.Kind)
	}
	sum := sha1.Sum(b)
	return string(sum[:])
}
