{"command":"cat > /tmp/gen/mut.py <<'EOF'
import random, sys, os
sys.path.insert(0, '/tmp/gen')
from gogen import G

class Mut(G):
    pass

def gen_func_lines(g, rnd, name):
    # list of statement strings at top level of body
    n = rnd.randint(3, 10)
    return [g.stmt(1, "\t") for _ in range(n)]

def render(name, stmts, recv=""):
    return "func %s%s() {\n" % (recv, name) + "".join("\t" + s + "\n" for s in stmts) + "}\n"

def main(path, seed, nfiles):
    rnd = random.Random(seed)
    g = G(rnd)
    os.makedirs(path, exist_ok=True)
    bases = [gen_func_lines(g, rnd, "B%d" % i) for i in range(rnd.randint(3, 8))]
    cnt = 0
    for fi in range(nfiles):
        parts = ["package p\n"]
        for _ in range(rnd.randint(2, 6)):
            b = list(rnd.choice(bases))
            op = rnd.randint(0, 5)
            if op == 1 and len(b) > 1:
                del b[rnd.randrange(len(b))]
            elif op == 2:
                b.insert(rnd.randint(0, len(b)), g.stmt(1, "\t"))
            elif op == 3:
                b[rnd.randrange(len(b))] = g.stmt(1, "\t")
            elif op == 4:
                # wrap a slice in a block / if
                i = rnd.randrange(len(b)); j = rnd.randint(i, len(b))
                inner = "".join("\t\t" + s.replace("\n", "\n\t") + "\n" for s in b[i:j])
                b[i:j] = ["if %s {\n%s\t}" % (g.hexpr(1), inner)]
            elif op == 5:
                b = b + list(rnd.choice(bases))
            cnt += 1
            parts.append(render("F%d" % cnt, b, rnd.choice(["", "", "(s *S) "])))
        open(os.path.join(path, "f%d.go" % fi), "w").write("\n".join(parts))

if __name__ == "__main__":
    main(sys.argv[1], int(sys.argv[2]), int(sys.argv[3]) if len(sys.argv) > 3 else 4)
EOF
